import styled from 'styled-components';
import { useState } from 'react';

const ContactSection = styled.section`
  width: 100%;
  max-width: 600px;
  margin: 4rem auto 0 auto;
  padding: 3rem 2rem 4rem 2rem;
  background: ${({ theme }) => theme.bg === '#fff' ? '#f8f8f8' : '#111'};
  border-radius: 18px;
  box-shadow: 0 2px 24px 0 rgba(0,0,0,0.10);
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const ContactTitle = styled.h2`
  font-size: 2.1rem;
  font-weight: 700;
  margin-bottom: 1.2rem;
  color: ${({ theme }) => theme.bg === '#fff' ? '#222' : '#fff'};
`;

const ContactForm = styled.form`
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 1.2rem;
`;

const Input = styled.input`
  padding: 0.9rem 1.1rem;
  border-radius: 7px;
  border: 1px solid ${({ theme }) => theme.bg === '#fff' ? '#ccc' : '#222'};
  background: ${({ theme }) => theme.bg === '#fff' ? '#fff' : '#181818'};
  color: ${({ theme }) => theme.bg === '#fff' ? '#222' : '#fff'};
  font-size: 1rem;
  transition: border 0.18s;
  &:focus {
    outline: none;
    border-color: #888;
  }
`;

const TextArea = styled.textarea`
  padding: 0.9rem 1.1rem;
  border-radius: 7px;
  border: 1px solid ${({ theme }) => theme.bg === '#fff' ? '#ccc' : '#222'};
  background: ${({ theme }) => theme.bg === '#fff' ? '#fff' : '#181818'};
  color: ${({ theme }) => theme.bg === '#fff' ? '#222' : '#fff'};
  font-size: 1rem;
  min-height: 120px;
  resize: vertical;
  transition: border 0.18s;
  &:focus {
    outline: none;
    border-color: #888;
  }
`;

const Button = styled.button`
  padding: 0.9rem 1.5rem;
  border-radius: 7px;
  border: none;
  background: #fff;
  color: #000;
  font-weight: 700;
  font-size: 1.08rem;
  cursor: pointer;
  transition: background 0.18s, color 0.18s;
  box-shadow: 0 1px 8px 0 rgba(0,0,0,0.08);
  &:hover, &:focus {
    background: #000;
    color: #fff;
  }
`;

const SuccessMsg = styled.div`
  color: #4caf50;
  font-size: 1.08rem;
  margin-top: 1rem;
  text-align: center;
`;

const Contact = () => {
  const [form, setForm] = useState({ name: '', email: '', message: '' });
  const [submitted, setSubmitted] = useState(false);

  const handleChange = e => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = e => {
    e.preventDefault();
    setSubmitted(true);
    setForm({ name: '', email: '', message: '' });
    // Integrate with Formspree/Netlify for real submissions
  };

  return (
    <ContactSection id="contact">
      <ContactTitle>Contact Me</ContactTitle>
      <ContactForm onSubmit={handleSubmit} autoComplete="off">
        <Input
          type="text"
          name="name"
          placeholder="Your Name"
          value={form.name}
          onChange={handleChange}
          required
        />
        <Input
          type="email"
          name="email"
          placeholder="Your Email"
          value={form.email}
          onChange={handleChange}
          required
        />
        <TextArea
          name="message"
          placeholder="Your Message"
          value={form.message}
          onChange={handleChange}
          required
        />
        <Button type="submit">Send Message</Button>
      </ContactForm>
      {submitted && <SuccessMsg>Thank you! Your message has been sent.</SuccessMsg>}
    </ContactSection>
  );
};

export default Contact;
